#!/usr/bin/env bash
# Attach trimmed.log to the ticket and notify the channel.
echo "upload $(date -u +%Y-%m-%dT%H:%M:%SZ)" >> .effects.log

arguments.command:
python3 - <<'EOF'
lines = open('deploy.log').read().splitlines()
for l in lines:
    if l.startswith('ERROR'):
        print(len(l), l)
EOF
